import React from 'react'
import { format } from 'date-fns'
import { Icon, Badge } from 'antd'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'
import { StyledAntdButton } from '../../../../../../components/uielements/customButton'

const handleDownloadClick = (request, fileId, status) => {
  request({ file_id: fileId, status })
}

export const fileUploadsColumns = (history, downloadFileUploads, cancelFileRequest, resetError) => ([

  {
    title: 'Action',
    width: 80,
    fixed: 'left',
    key: 1,
    render: (rowData) => (
      <PermissionCheckerV2 requiredPermission='ops.eb_view_company_file_info'>
        <Icon
          type='eye'
          twoToneColor='#0180c8'
          theme='twoTone'
          style={{ cursor: 'pointer' }}
          onClick={() => history.push(`file-uploads/${rowData.id}`)}
        />
      </PermissionCheckerV2>
    )
  },
  {
    title: 'Name',
    dataIndex: 'name',
    key: 2
  },
  {
    title: 'Operation',
    dataIndex: 'template__operation',
    key: 'template__operation'
  },
  {
    title: 'Status',
    dataIndex: 'status',
    key: 3
  },
  {
    title: 'Row Status',
    dataIndex: 'filerows_status_count',
    render: (colData) => (
      <>
        <Badge count={`Success: ${colData.success_rows}`} style={{ backgroundColor: 'rgb(52, 199, 89)', marginRight: 5, display: 'block' }} />
        <Badge count={`Failed: ${colData.failed_rows}`} style={{ backgroundColor: 'rgb(255, 59, 48)', marginRight: 5, display: 'block' }} />
        <Badge count={`Duplicate: ${colData.duplicate_rows}`} style={{ backgroundColor: 'rgb(90, 200, 250)', marginRight: 5, display: 'block' }} />
      </>
    ),
    key: 4,
    width: 150
  },
  {
    title: 'Updated At',
    dataIndex: 'updated_at',
    render: date => format(date, 'DD MMMM YYYY'),
    key: 5
  },
  {
    title: 'Action',
    render: (rowData) => (
      <>
        <PermissionCheckerV2 requiredPermission='ops.eb_download_company_file'>
          <StyledAntdButton
            type='customSuccess'
            className='display-block'
            shape='round' icon='download' size='small'
            onClick={() => {
              resetError(['DOWNLOAD_FILE_UPLOADS_ERROR'])
              handleDownloadClick(downloadFileUploads, rowData.id, 'SUCCESS')
            }}
          >
            Download Success
          </StyledAntdButton>
          <StyledAntdButton
            type='customDanger'
            className='display-block'
            shape='round' icon='download' size='small'
            onClick={() => {
              resetError(['DOWNLOAD_FILE_UPLOADS_ERROR'])
              handleDownloadClick(downloadFileUploads, rowData.id, 'FAILED')
            }}
          >
            Download failed
          </StyledAntdButton>

        </PermissionCheckerV2>
        {
          ['UPLOADED', 'INPROCESS'].includes(rowData.status)
            ? (
              <PermissionCheckerV2 requiredPermission='ops.eb_cancel_company_file_processing'>
                <StyledAntdButton
                  type='customPrimary'
                  shape='round'
                  icon='close'
                  size='small'
                  onClick={() => {
                    resetError(['CANCEL_FILE_ERROR'])
                    cancelFileRequest({ file_id: rowData.id })
                  }}
                >
                  Cancel
                </StyledAntdButton>
              </PermissionCheckerV2>
              )
            : null
        }
      </>
    ),
    key: 6
  }

])
