/* eslint-disable react-hooks/exhaustive-deps */
import React, { useState, useEffect, useCallback } from 'react'
import {
  Table,
  Row,
  Col,
  Spin,
  Typography,
  Button,
  Icon,
  Alert,
  message
} from 'antd'
import LayoutContent from '../../../../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../../../../components/utility/layoutWrapper'
import { fileUploadsColumns } from './constants'
import { useFileUploadList, useDownloadFileUploads, useCancelFile } from '../../../state/ParticipantsFileUploads/hooks/useParticipantsFileUploads'
import { downloadDataFromUrl } from '../../../../../../helpers/utility'
import { useResetState } from '../../../state/hooks'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'

const { Title } = Typography

const FileUploads = ({ history, match, ...props }) => {
  const [listData, setListData] = useState([])
  const [listMetaData, setListMetaData] = useState({})
  const [{ fileUploadsListData }, request] = useFileUploadList()
  const { cancelFileData, cancelFileRequest } = useCancelFile()
  const [{ FILE_UPLOADS_LIST_LOADER }] = useLoaderContextValue()
  const [{ FILE_UPLOADS_LIST_ERROR, fileUploadsListStatus, cancelFileStatus, DOWNLOAD_FILE_UPLOADS_ERROR, downloadFileUploadsStatus, CANCEL_FILE_ERROR }] = useErrorContextValue()
  const [{ downloadFileUploadsData }, downloadFileUploads] = useDownloadFileUploads()
  const { resetState } = useResetState()
  const { resetError } = useResetError()

  useEffect(() => {
    return () => {
      resetError([
        'FILE_UPLOADS_LIST_ERROR',
        'DOWNLOAD_FILE_UPLOADS_ERROR',
        'CANCEL_FILE_ERROR',
        'fileUploadsListData',
        'fileUploadsListStatus',
        'downloadFileUploadsData',
        'downloadFileUploadsStatus',
        'cancelFileData',
        'cancelFileStatus'
      ])
    }
  }, [])

  useEffect(() => {
    if (fileUploadsListData) {
      if (fileUploadsListData.data) {
        setListData(fileUploadsListData.data)
        setListMetaData(fileUploadsListData.meta_data)
      }
    } else {
      if (FILE_UPLOADS_LIST_ERROR === undefined) {
        request({ company_id: match.params.id })
      }
    }
  }, [fileUploadsListData])

  const handleTableChange = (params) => {
    resetError(['DOWNLOAD_FILE_UPLOADS_ERROR', 'FILE_UPLOADS_LIST_ERROR', 'CANCEL_FILE_ERROR'])
    const query = {
      company_id: match.params.id,
      page: params.current,
      per_page: params.pageSize
    }
    request(query)
  }

  const goBack = useCallback(() => {
    history.goBack()
  }, [history])

  useEffect(() => {
    if (downloadFileUploadsData && downloadFileUploadsData.url && !DOWNLOAD_FILE_UPLOADS_ERROR) {
      downloadDataFromUrl(downloadFileUploadsData.url)
      resetState(['downloadFileUploadsData', 'downloadFileUploadsStatus'])
    }
  }, [downloadFileUploadsData])

  useEffect(() => {
    if (!CANCEL_FILE_ERROR && cancelFileData && cancelFileData.message === 'Success') {
      message.success('File cancellation successfull')
      request({
        company_id: match.params.id,
        page: listMetaData.page,
        per_page: listMetaData.page_size
      })
      resetState(['cancelFileData', 'cancelFileStatus'])
    }
  }, [cancelFileData, cancelFileStatus])

  return (
    <LayoutContentWrapper>
      <Button onClick={goBack}><Icon type='arrow-left' /> Back</Button>
      <LayoutContent>
        {(DOWNLOAD_FILE_UPLOADS_ERROR) && <Alert type='error' message={downloadFileUploadsStatus} banner />}
        {(FILE_UPLOADS_LIST_ERROR) && <Alert type='error' message={fileUploadsListStatus} banner />}
        {(CANCEL_FILE_ERROR) && <Alert type='error' message={cancelFileStatus} banner />}
        <Row>
          <Col span={18}>
            <Title level={4}>Uploaded files List</Title>
          </Col>
        </Row>
        <Spin spinning={FILE_UPLOADS_LIST_LOADER}>
          <Table
            rowKey={({ id }) => id}
            columns={fileUploadsColumns(history, downloadFileUploads, cancelFileRequest, resetError)}
            dataSource={listData}
            onChange={handleTableChange}
            bordered
            pagination={{
              pageSize: listMetaData.page_size,
              total: listMetaData.total_records,
              current: listMetaData.page
            }}
          />
        </Spin>
      </LayoutContent>
    </LayoutContentWrapper>
  )
}

export default FileUploads
