export const useCompanyList = () => {
  const [{ companyListData }, dispatch] = useEBContextValue()
  //  follow this
  const [callApi] = useServiceRequest(dispatch)
  const request = async (payload = {}) => {
    await callApi(actions.geCompanyList(payload))
  }
  return [companyListData, request]
}

